// Une ligne, sans deux-points : n8n scinde le texte d'une Error dessus.
const f = $('Charger fiche').first().json;
throw new Error(
  `Acceptation de livraison en echec pour ${f.slug} — livreur et gerant ont ete prevenus du doute`,
);

// Une ligne, sans deux-points : n8n scinde le texte d'une Error dessus.
// Sans cette levee, poser continueErrorOutput rendrait la panne muette cote
// exploitant - on echangerait un silence contre un autre.
const f = $('Charger fiche').first().json;
throw new Error(
  `Branche Telegram en echec pour ${f.slug} — l utilisateur a recu un message de repli`,
);

// LE REFUS DE CANAL N EST PAS UNE PANNE DE LA PLATEFORME.
//
// `Charger fiche` appelle /api/internal/fiche, qui verifie le secret propre
// au marchand. Un secret faux ou absent rend 401 — la BONNE reponse. Un noeud
// HTTP, lui, traite tout non-2xx comme une panne : l execution passait en
// rouge, et ce workflow porte un errorWorkflow, donc une alerte partait.
//
// Consequence mesuree le 3 septembre 2026 : n importe qui connaissant l URL
// publique du webhook d un marchand faisait sonner le salon de veille avec un
// en-tete bidon, et brulait une execution n8n. Le banc de l assistante
// laissait la meme trace rouge a chaque passage.
const item = $input.first();
const err = (item && item.json && item.json.error) || (item && item.json) || {};
const code = String(err.httpCode ?? (err.context && err.context.httpCode) ?? err.status ?? '');

// FIN PROPRE, AUCUNE TRACE ROUGE. Le refus n est pas perdu pour autant :
// /api/internal/fiche le COMPTE, et la veille des chaines annonce le marchand
// dont la porte s ouvrait cette semaine et ne s ouvre plus. Voir
// src/lib/compteurCanal.ts — sans ce comptage, ce `return []` serait un
// angle mort, et il ne doit jamais le redevenir.
if (code === '401') return [];

// LE 404 NON PLUS : UN SLUG INCONNU N EST PAS UNE PANNE DE LA PLATEFORME.
//
// Meme defaut que le routeur WhatsApp, ferme le 4 septembre 2026 (PR #179), et
// laisse ouvert ici le meme jour : le correctif avait ete pose sur un seul des
// deux routeurs. L URL de celui-ci est ecrite en clair dans
// `telegramBranchement.ts`, et LE DEPOT EST PUBLIC — n importe qui peut donc
// POSTer un slug invente, la fiche rend 404, ce noeud levait, et l
// errorWorkflow faisait sonner le salon de veille.
//
// CE ROUTEUR EST LE PLUS EXPOSE DES DEUX : au 4 septembre, Zahara et Rose
// Monde sont toutes deux branchees en Telegram, et aucune en WhatsApp.
//
// CE 404 NE PEUT PAS ETRE UNE INDISPONIBILITE : /api/internal/fiche sort en
// 503 quand le registre ne repond pas, et ne rend 404 qu apres une recherche
// aboutie qui n a rien trouve.
//
// ET IL EST DEJA COMPTE : les deux routeurs appellent la MEME route, qui
// incremente un seau global avant de rendre 404. Voir `cleCanalSlugInconnu`
// dans src/lib/compteurCanal.ts. Le filet etait donc pose avant ce trou-ci.
if (code === '404') return [];

// TOUT LE RESTE RESTE BRUYANT : 5xx, 404, reseau — et toute forme d erreur
// qu on n a pas su lire. Se tromper ici doit rendre l execution ROUGE, jamais
// muette.
//
// LE MESSAGE TIENT SUR UNE LIGNE, ET SANS DEUX-POINTS. Mesure du 3 septembre
// 2026 sur l execution 8074 : n8n coupe un message lance depuis un noeud Code
// au premier deux-points et range la tete dans `description` — champ que
// « Alerte erreurs plateforme » ne lit pas. Le detail venant d un corps JSON
// en contient toujours un, et l exploitant recevait donc la QUEUE du message
// seule, privee de ce qui la nommait. Meme famille que le retour a la ligne,
// qui lui ne laisse que « Unknown error ».
const detail = String(err.message ?? err.description ?? 'sans detail')
  .replace(/[\r\n:]+/g, ' ')
  .replace(/\s+/g, ' ')
  .slice(0, 200);

throw new Error('Fiche marchand illisible (' + (code || 'sans code') + ') — ' + detail);
